// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint64 t0, uint64 delta, address actor) public {
        vm.assume(t0 > 0);
        vm.assume(delta >= 1);
        vm.assume(uint256(t0) + uint256(delta) < type(uint64).max);
        vm.assume(actor != address(0) && actor != address(c));

        vm.warp(t0);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");

        vm.warp(t0 + delta);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // Rule: after a success at t, any strictly later timestamp (>= t+1) is admissible.
        assertTrue(ok2, "second call at a strictly later timestamp must succeed");
    }
}
